"""Camera/proprioception-only controller for the single live episode.
Commands are recorded in commands.jsonl; no resets or privileged scene reads.
"""
import json,time,traceback,sys
from pathlib import Path
import numpy as np
from PIL import Image
from rcb_client import Robot
OUT=Path('/app/output'); RUNS=Path('/app/runs')
r=Robot(); spec=r.spec(); cams=list(spec['cameras']); seq=0
# Start from the already captured initial observation (no physics elapsed).
obs=None
def record(o,label):
 global obs,seq
 obs=o; seq+=1; folder=RUNS/f'{seq:03d}_{label}'
 o.save(str(folder)); (OUT/'latest.json').write_text(json.dumps({'folder':str(folder),'meta':o.meta}))
 print(json.dumps({'folder':str(folder),'eef':o.meta['proprio']['now'][26:29],'joints':o.meta['proprio']['now'][:13],'time_left':o.meta['time_left_s']}),flush=True)
 return o
def observe(label='obs'):
 return record(r.get_obs(include_depth=True,video='none'),label)
def act(a,n=1,label='action'):
 a=np.asarray(a,dtype=float)
 if a.ndim==1:a=np.tile(a,(n,1))
 return record(r.submit('ee_delta',a,include_depth=True,video='none',note=label),label)
def step(delta=(0,0,0),rot=(0,0,0),grip=-1,base=(0,0,0),torso=0,mode=-1,n=1,label='step'):
 return act([*delta,*rot,grip,*base,torso,mode],n,label)
def world(u,v,cam='robot0_agentview_center',o=None):
 o=obs if o is None else o
 d=o.depth[cam];d=d[-1] if d.ndim==3 else d
 z=float(d[int(v),int(u)]); c=o.meta['cameras'][cam]; K=np.array(c['intrinsic_cv']); T=np.array(c['cam2world_gl']); p=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z])
 return (T[:3,:3]@p+T[:3,3]).tolist()
def goto(target,grip=-1,gain=.65,max_step=.35,tol=.008,iters=25,label='goto'):
 # Base yaw is from proprio; initial camera forward gives initial heading.
 initial_heading=0.019624
 for i in range(iters):
  p=np.array(obs.meta['proprio']['now']); err=np.array(target)-p[26:29]
  if np.linalg.norm(err)<tol:break
  yaw=initial_heading+p[2]; c,s=np.cos(yaw),np.sin(yaw)
  local=np.array([[c,s,0],[-s,c,0],[0,0,1]])@err
  a=np.clip(gain*local/.05,-max_step,max_step)
  step(a,grip=grip,n=3,label=label+str(i))
 return obs
observe('start')
print('READY',flush=True)
for line in sys.stdin:
 try:
  cmd=json.loads(line);(OUT/'commands.jsonl').open('a').write(json.dumps(cmd)+'\n')
  kind=cmd.pop('kind')
  if kind=='step':step(**cmd)
  elif kind=='goto':goto(**cmd)
  elif kind=='observe':observe(**cmd)
  elif kind=='world':print(json.dumps(world(**cmd)),flush=True)
  elif kind=='exec':exec(cmd['code'],globals())
  elif kind=='stop':break
  print('READY',flush=True)
 except Exception:traceback.print_exc();print('READY',flush=True)
